with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['CHROMIUM_BIN'],headless=True,args=['--no-sandbox']); page=b.new_page(viewport={'width':390,'height':460}); requests=[];page.on('request',lambda q:requests.append(q.url));page.set_content('<dialog id="dialog"><div id="dialog-body"></div></dialog><div id="summary"></div><pre id="state"></pre><button id="undo">Undo timing</button>')
 for f in ['styles.css','workspace.css']:page.add_style_tag(content=(r/f).read_text())
