 page.add_script_tag(content="""window.fx={p:H3.newProject(),undo:[]};fx.p.mode='managed';fx.p.windows[0].frames=124;fx.p.windows[0].detail='<d>[English] One little turn.</d>';fx.p.windows.push(H3.newWindow('Next',124,18));const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');fx.ui=H3TimingUI.create({$:s=>document.querySelector(s),esc,project:()=>fx.p,current:()=>fx.p.windows[0],mutate:f=>{fx.undo.push(JSON.stringify(fx.p));f();},toast:s=>document.querySelector('#state').textContent=s,openDialog:(t,html)=>{document.querySelector('#dialog-body').innerHTML=html;if(!document.querySelector('#dialog').open)document.querySelector('#dialog').showModal();}});document.querySelector('#summary').innerHTML=fx.ui.summary(fx.p.windows[0]);document.querySelector('#undo').onclick=()=>{fx.p=JSON.parse(fx.undo.pop());document.querySelector('#state').textContent='Undone; frames='+fx.p.windows[0].frames;};""")
 page.locator('[data-timing-advisor=open]').click();assert 'no verb-duration guess' in page.locator('#dialog-body').inner_text().lower();page.locator('#advisor-capacity').fill('15');page.locator('#advisor-plan').fill(json.dumps({'version':1,'actionsReviewed':True,'groups':[{'label':'Turn','members':[{'kind':'action','label':'visible turn','minSeconds':2,'maxSeconds':4}]},{'label':'Line with reaction','members':[{'kind':'dialogue','line':0,'label':'first line','minSeconds':1,'maxSeconds':2},{'kind':'reaction','label':'look','minSeconds':1,'maxSeconds':3}]}]}));page.locator('[data-timing-advisor=save]').click();assert '2.00–4.00' in page.locator('#dialog-body').inner_text();page.screenshot(path=str(r.parent/'timing-advisor-mobile.png'));page.locator('#advisor-extend-seconds').fill('12');page.locator('[data-timing-advisor=extend-preview]').click();assert 'Shift 1 downstream windows' in page.locator('#app-confirm').inner_text();page.locator('[data-app-confirm=cancel]').click();page.locator('[data-timing-advisor=extend-preview]').click();page.locator('[data-app-confirm=accept]').click();assert 'stale' in page.locator('#dialog-body').inner_text().lower();page.keyboard.press('Escape');page.locator('#undo').click();page.keyboard.press('Escape');page.locator('#undo').click();assert 'frames=124' in page.locator('#state').inner_text();assert not requests
 page.evaluate('fx.ui.open()');page.locator('#advisor-extend-seconds').fill('15');page.locator('[data-timing-advisor=extend-preview]').click();assert '362 generated frames (15.083 s)' in page.locator('#dialog-body').inner_text();assert 'No change applied' in page.locator('#dialog-body').inner_text();
